{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C05","C18","C19","C20","C23","C52","C53","C54","C55","C57","C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"],
  "contradictory_card_ids": ["C10"],
  "prediction_basis_card_ids": ["C05","C18","C19","C20","C23","C52","C53","C54","C55","C57","C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"],
  "claims": [
    {
      "claim": "Meptazinol, a phenolic opioid, had F 27.9±5.3% in cirrhosis and this was a four-fold increase over controls, implying a non-cirrhotic control F near 7%; this is the most direct threshold-relevant F evidence for a phenolic opioid and supports F<20% for the similarly phenolic morphinan query.",
      "card_ids": ["C05","C19","C23"]
    },
    {
      "claim": "Morphine, a close morphinan analog, is subject to intestinal P-gp efflux (C52,C54,C55) and extensive small-intestinal UGT glucuronidation (C53,C57), providing mechanistic evidence for presystemic loss in the same structural class.",
      "card_ids": ["C52","C53","C54","C55","C57"]
    },
    {
      "claim": "L6 hepatic-clearance records show morphine has substantial hepatic clearance in isolated perfused rat liver (26.0±1.7 mL/min, C66), UGT-mediated intrinsic clearance in recombinant human UGTs (C63,C70,C62), rat liver microsomal glucuronidation activity (C67), and is a UGT2B7 probe substrate (C68); buprenorphine, another morphinan, has human liver microsomal glucuronidation clearance of ~13.9-18.4 mL/min/kg (C60,C61,C64,C65,C69,C71). These support substantial first-pass hepatic metabolism for phenolic morphinans.",
      "card_ids": ["C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"]
    },
    {
      "claim": "L2 records note that cirrhosis increases oral bioavailability of pentazocine, meperidine, and other opioids due to reduced first-pass metabolism (C18,C20), implying these opioids have meaningful first-pass loss under normal conditions.",
      "card_ids": ["C18","C20"]
    },
    {
      "claim": "High-F contexts are either cirrhosis-dependent or not established for the non-cirrhotic query (pentazocine C04/C11, meperidine C07/C13, ciramadol C10) or structurally unrelated (paliperidone C01/C02/C15, haloperidol C08/C14, BI 425809 C09, ACT-1004-1239 C03/C06, UDCA C12); they do not provide affirmative evidence for F>=20% in the non-cirrhotic query.",
      "card_ids": ["C01","C02","C03","C04","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15"]
    },
    {
      "claim": "Samidorphan, a related morphinan, has high Caco-2 A-B Papp (18.77 x 10^-6 cm/s, C48), indicating permeability is not the limiting step, but this does not address first-pass metabolism and does not provide an oral F estimate.",
      "card_ids": ["C48"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"]
    }
  ],
  "evidence_gaps": [
    "No direct nalbuphine-specific absolute oral bioavailability measurement is present in the supplied records.",
    "No nalbuphine-specific hepatic clearance or metabolic-stability experiment is provided; L6 records are for morphine and buprenorphine.",
    "The meptazinol control F (~7%) is inferred from the stated four-fold increase over controls rather than reported as a direct numeric control value.",
    "Normal-condition F values for pentazocine, meperidine, and ciramadol are not directly provided; their high-F contexts are cirrhosis-dependent or not clearly transferable.",
    "The extent of nalbuphine first-pass glucuronidation is not quantified in the supplied evidence.",
    "L3/L4 records are mostly for unrelated molecules and do not provide query-specific exposure or permeability data."
  ],
  "decision_summary": "L6 hepatic-clearance/metabolic-stability records for morphine and buprenorphine add mechanistic support for substantial first-pass glucuronidation in phenolic morphinans, strengthening the low prediction; combined with meptazinol control-F inference (~7%) and morphine gut-wall efflux/UGT evidence, F<20% remains better supported, though no direct nalbuphine F is available."
}

